/** Places, tracks and cancels customer orders. */

export interface Order {}

export type OrderStatus = string;

export type OrderId = string;

/** Place an order from a cart. */
export function placeOrder(cart: Cart, customer: CustomerId): Promise<Order> {
  checkout.run();
  orderRepository.save();
  orderEvents.placed();
}

/** Look up one order. */
export function getOrder(id: OrderId): Promise<Order> {
  orderRepository.find();
}

/** Cancel an order that has not shipped. */
export function cancelOrder(id: OrderId, reason: string): Promise<Order> {
  orderRepository.find();
  orderRepository.save();
  refunds.refund();
  orderEvents.cancelled();
}

/** List a customer's orders, newest first. */
export function listOrders(customer: CustomerId): Promise<Order[]> {
  orderRepository.byCustomer();
}

