/** What the shop sells. */

export interface Product {}

export interface Page<T> {}

/** List products, a page at a time. */
export function list(page: PageRequest): Promise<Page<Product>> {
  productRepository.page();
}

/** Look up one product. */
export function get(sku: Sku): Promise<Product> {
  productRepository.find();
  images.urlFor();
}

/** Publish a new product. */
export function publish(draft: ProductDraft): Promise<Product> {
  products.validate();
  productRepository.save();
  search.index();
  eventBus.publish();
}

/** Stop selling a product without deleting it. */
export function discontinue(sku: Sku): Promise<void> {
  productRepository.find();
  productRepository.save();
}

